-- Interactive puzzle questions for all three subjects — at least one for every topic. Safe to run again: existing rows with
-- the same id are updated, nothing is deleted. Run supabase/schema.sql first.
-- A puzzle row stores no answer: `puzzle` holds the board's settings and the website draws a
-- fresh board every time (see README → Practice questions → Puzzles).
on conflict (id) do update set
  topic = excluded.topic, sort_order = excluded.sort_order, kind = excluded.kind,
  prompt = excluded.prompt, options = excluded.options, puzzle = excluded.puzzle,
  hint = excluded.hint, tag = excluded.tag, answer = excluded.answer,
  tags = excluded.tags, explain = excluded.explain;
