insert into public.problems (id, topic, sort_order, kind, prompt, options, puzzle, hint, tag, answer, tags, explain)
values
  ('pz-daa-bfs', 'traversal', 100, 'puzzle', 'Breadth-first search, by hand.', null, '{"type":"bfs","nodes":7,"extra":3}'::jsonb, 'Keep a queue. Take the vertex at the front and add its unvisited neighbours in alphabetical order.', 'Mixed up BFS and DFS order', null, '{}'::jsonb, ''),
  ('pz-daa-dfs', 'traversal', 101, 'puzzle', 'Depth-first search, by hand.', null, '{"type":"dfs","nodes":7,"extra":3}'::jsonb, 'Go to the alphabetically first unvisited neighbour. At a dead end, back up to the last vertex that still has one.', 'Mixed up DFS and BFS order', null, '{}'::jsonb, ''),
  ('pz-daa-topo', 'topological', 102, 'puzzle', 'Topological sort, by hand.', null, '{"type":"topo","nodes":6}'::jsonb, 'Pick any vertex that no remaining arrow points into, then remove it and its arrows.', 'Placed a vertex before one of its prerequisites', null, '{}'::jsonb, ''),
  ('pz-daa-dijkstra', 'dijkstra', 103, 'puzzle', 'Run Dijkstra''s algorithm.', null, '{"type":"dijkstra","nodes":6,"extra":4}'::jsonb, 'Track the best known distance to each vertex. Always finalise the unfinished vertex with the smallest one.', 'Finalised a vertex before its shortest distance was known', null, '{}'::jsonb, ''),
  ('pz-daa-shortest', 'shortest', 104, 'puzzle', 'Shortest paths from one source.', null, '{"type":"dijkstra","nodes":7,"extra":5}'::jsonb, 'A vertex''s distance is final once it''s the smallest among the unfinished vertices; then relax its edges.', 'Finalised a vertex before its shortest distance was known', null, '{}'::jsonb, ''),
  ('pz-daa-kruskal', 'mst', 105, 'puzzle', 'Build a minimum spanning tree with Kruskal''s algorithm.', null, '{"type":"kruskal","nodes":6,"extra":4}'::jsonb, 'Sort the edges by weight. Take the cheapest edge that doesn''t close a cycle.', 'Took an edge that closes a cycle, or not the cheapest', null, '{}'::jsonb, ''),
  ('pz-daa-hamilton', 'hamiltonian', 106, 'puzzle', 'Find a Hamiltonian cycle by backtracking.', null, '{"type":"hamiltonian","nodes":7}'::jsonb, 'Prefer vertices with few edges left: they''re easiest to get stranded at. Step back as soon as a branch is a dead end.', 'Couldn''t backtrack to a Hamiltonian cycle', null, '{}'::jsonb, ''),
  ('pz-daa-selection', 'sorting', 107, 'puzzle', 'Play selection sort.', null, '{"type":"selection-sort","size":7}'::jsonb, 'Scan the whole unsorted part (the bars not yet green) and find its smallest value.', 'Didn''t pick the minimum of the unsorted part', null, '{}'::jsonb, ''),
  ('pz-daa-bst', 'trees', 108, 'puzzle', 'Search a binary search tree.', null, '{"type":"bst-search","nodes":9}'::jsonb, 'Start at the root. Smaller keys are always to the left, larger ones to the right.', 'Didn''t follow the BST search path', null, '{}'::jsonb, ''),
  ('pz-daa-queens', 'paradigms', 109, 'puzzle', 'Backtracking: the N-Queens problem.', null, '{"type":"queens","n":6}'::jsonb, 'Place one queen per row. When a row has no safe square, move the queen in the row above.', 'Placed queens that attack each other', null, '{}'::jsonb, ''),
  ('pz-ds-maze', 'ds-maze', 110, 'puzzle', 'Escape the maze.', null, '{"type":"maze","size":7}'::jsonb, 'At every junction try one way; at a dead end go back to the last junction with an untried corridor.', 'Lost the way in the maze', null, '{}'::jsonb, ''),
  ('pz-ds-queens', 'ds-backtracking', 111, 'puzzle', 'Backtracking: place the queens.', null, '{"type":"queens","n":5}'::jsonb, 'Go row by row. If a row has no safe square left, go back one row and move that queen on.', 'Placed queens that attack each other', null, '{}'::jsonb, ''),
  ('pz-ds-queens-8', 'ds-backtracking', 112, 'puzzle', 'The classic eight queens.', null, '{"type":"queens","n":8}'::jsonb, 'Go row by row. If a row has no safe square left, go back one row and move that queen on.', 'Placed queens that attack each other', null, '{}'::jsonb, ''),
  ('pz-ds-hanoi-3', 'ds-hanoi', 113, 'puzzle', 'Tower of Hanoi with three disks.', null, '{"type":"hanoi","disks":3}'::jsonb, 'With an odd number of disks, the smallest disk''s first move goes straight to the target peg.', 'Used more moves than needed', null, '{}'::jsonb, ''),
  ('pz-ds-hanoi-4', 'ds-hanoi', 114, 'puzzle', 'Tower of Hanoi with four disks.', null, '{"type":"hanoi","disks":4}'::jsonb, 'Move the top three disks to the spare peg first, then the big disk, then the three on top of it.', 'Used more moves than needed', null, '{}'::jsonb, ''),
  ('pz-ds-inorder', 'ds-tree-basics', 115, 'puzzle', 'Inorder traversal.', null, '{"type":"tree-order","nodes":7,"order":"inorder"}'::jsonb, 'Left subtree, then the node, then the right subtree. In a BST that lists the keys in sorted order.', 'Visited nodes out of inorder', null, '{}'::jsonb, ''),
  ('pz-ds-preorder', 'ds-tree-basics', 116, 'puzzle', 'Preorder traversal.', null, '{"type":"tree-order","nodes":7,"order":"preorder"}'::jsonb, 'The node first, then its whole left subtree, then its right subtree.', 'Visited nodes out of preorder', null, '{}'::jsonb, ''),
  ('pz-ds-postorder', 'ds-expression-tree', 117, 'puzzle', 'Postorder traversal.', null, '{"type":"tree-order","nodes":7,"order":"postorder"}'::jsonb, 'Both subtrees first (left, then right), the node last. The root is always the last one.', 'Visited nodes out of postorder', null, '{}'::jsonb, ''),
  ('pz-ds-level', 'ds-tree-basics', 118, 'puzzle', 'Level-order traversal.', null, '{"type":"tree-order","nodes":8,"order":"level"}'::jsonb, 'Row by row from the top, left to right in each row — that''s BFS on a tree.', 'Visited nodes out of level order', null, '{}'::jsonb, ''),
  ('pz-ds-bst', 'ds-bst', 119, 'puzzle', 'Search the BST.', null, '{"type":"bst-search","nodes":10}'::jsonb, 'Compare with each node from the root down: smaller goes left, larger goes right.', 'Didn''t follow the BST search path', null, '{}'::jsonb, ''),
  ('pz-ds-selection', 'ds-elementary-sorts', 120, 'puzzle', 'Play selection sort.', null, '{"type":"selection-sort","size":8}'::jsonb, 'Scan the whole unsorted part (the bars not yet green) and find its smallest value.', 'Didn''t pick the minimum of the unsorted part', null, '{}'::jsonb, ''),
  ('pz-ds-bfs', 'ds-graph-traversal', 121, 'puzzle', 'Breadth-first search.', null, '{"type":"bfs","nodes":8,"extra":3}'::jsonb, 'Use a queue. Visit all neighbours of the front vertex (alphabetically) before going deeper.', 'Mixed up BFS and DFS order', null, '{}'::jsonb, ''),
  ('pz-ds-dfs', 'ds-graph-traversal', 122, 'puzzle', 'Depth-first search.', null, '{"type":"dfs","nodes":8,"extra":3}'::jsonb, 'Use a stack (or recursion). Always go deeper first, alphabetically; back up only at a dead end.', 'Mixed up DFS and BFS order', null, '{}'::jsonb, ''),
  ('pz-ds-topo', 'ds-topo', 123, 'puzzle', 'Topological ordering.', null, '{"type":"topo","nodes":7}'::jsonb, 'Pick any vertex with no incoming arrows from vertices you haven''t placed yet.', 'Placed a vertex before one of its prerequisites', null, '{}'::jsonb, ''),
  ('pz-la-combination', 'la-span', 124, 'puzzle', 'Build a linear combination.', null, '{"type":"combination","range":6}'::jsonb, 'Scale each vector by its coefficient, then add them tip to tail.', 'Couldn''t build the linear combination', null, '{}'::jsonb, ''),
  ('pz-la-basis', 'la-basis', 125, 'puzzle', 'Coordinates in a basis.', null, '{"type":"combination","range":7}'::jsonb, 'The coefficients are coordinates in the basis {u, v}: walk along u, then along v.', 'Couldn''t build the linear combination', null, '{}'::jsonb, ''),
  ('pz-la-transform', 'la-transform', 126, 'puzzle', 'Apply a linear map.', null, '{"type":"transform","range":6}'::jsonb, 'A·p = p₁ × (first column of A) + p₂ × (second column of A).', 'Applied the matrix incorrectly', null, '{}'::jsonb, ''),
  ('pz-la-eigen', 'la-eigen', 127, 'puzzle', 'Find an eigenvector.', null, '{"type":"eigenvector","range":6}'::jsonb, 'Hover a point: the hint draws A·x. An eigenvector''s arrow and A·x lie on the same line.', 'Picked a vector that A turns off its line', null, '{}'::jsonb, ''),
  ('pz-la-projection', 'la-orth-proj', 128, 'puzzle', 'Project onto a line.', null, '{"type":"projection","range":6}'::jsonb, 'proj = (p·u / u·u) · u. The leftover p − proj must be perpendicular to u.', 'Projected incorrectly', null, '{}'::jsonb, ''),
  ('pz-daa-ram', 'ram', 129, 'puzzle', 'Count the primitive operations.', null, '{"type":"op-count"}'::jsonb, 'A loop header runs once more than its body: the last test fails and exits.', 'Miscounted how often a line runs', null, '{}'::jsonb, ''),
  ('pz-daa-growth', 'asymptotic', 130, 'puzzle', 'Order the growth rates.', null, '{"type":"growth","count":7}'::jsonb, 'Compare large n: logs < powers of n < exponentials < factorials. n log n sits between n and n^1.5.', 'Misordered growth rates', null, '{}'::jsonb, ''),
  ('pz-daa-loops', 'complexity', 131, 'puzzle', 'Trace → count → derive.', null, '{"type":"loop-count"}'::jsonb, 'Count the inner line for each outer iteration, then add them up. A loop that halves k runs about log₂ n times.', 'Miscounted the loop iterations', null, '{}'::jsonb, ''),
  ('pz-daa-counting', 'linear', 132, 'puzzle', 'Counting sort, by hand.', null, '{"type":"counting-sort"}'::jsonb, 'First count each value. Then each running total adds the counts of all values up to and including it.', 'Miscounted the counting-sort table', null, '{}'::jsonb, ''),
  ('pz-daa-heap', 'heaps', 133, 'puzzle', 'Sift a key through a heap.', null, '{"type":"heap","heap":"max"}'::jsonb, 'Sift up: swap with the parent while bigger. Sift down: swap with the larger child while that child is bigger.', 'Moved the key the wrong way through the heap', null, '{}'::jsonb, ''),
  ('pz-daa-hashing', 'hashing', 134, 'puzzle', 'Open addressing with linear probing.', null, '{"type":"hashing","probe":"linear","size":11}'::jsonb, 'Compute k mod m. If that slot is taken, try the next one (wrapping round to 0).', 'Placed a key in the wrong slot', null, '{}'::jsonb, ''),
  ('pz-daa-matching', 'matching', 135, 'puzzle', 'Find every match.', null, '{"type":"string-match"}'::jsonb, 'Slide the pattern one position at a time and compare it with the text underneath.', 'Missed or invented a pattern match', null, '{}'::jsonb, ''),
  ('pz-daa-adjmatrix', 'representations', 136, 'puzzle', 'Build the adjacency matrix.', null, '{"type":"adjacency-matrix","nodes":5}'::jsonb, 'For every edge u–v put a 1 in row u, column v, and in row v, column u.', 'Built the adjacency matrix incorrectly', null, '{}'::jsonb, ''),
  ('pz-daa-scc', 'components', 137, 'puzzle', 'Strongly connected components.', null, '{"type":"components","mode":"scc"}'::jsonb, 'v belongs with x only if you can go x → v and also v → x along arrows.', 'Mixed up reachability with strong connectivity', null, '{}'::jsonb, ''),
  ('pz-daa-articulation', 'biconnected', 138, 'puzzle', 'Find the articulation points.', null, '{"type":"articulation","find":"points"}'::jsonb, 'Imagine deleting a vertex and its edges. If the rest falls apart, it is an articulation point.', 'Misidentified articulation points', null, '{}'::jsonb, ''),
  ('pz-daa-fractional', 'greedy', 139, 'puzzle', 'Greedy fractional knapsack.', null, '{"type":"fractional-knapsack"}'::jsonb, 'Work out value ÷ weight for each item; take the best ratio first.', 'Didn''t take items by value per weight', null, '{}'::jsonb, ''),
  ('pz-daa-huffman', 'huffman', 140, 'puzzle', 'Build a Huffman tree.', null, '{"type":"huffman"}'::jsonb, 'Always merge the two trees with the smallest weights.', 'Merged trees that weren''t the two lightest', null, '{}'::jsonb, ''),
  ('pz-daa-pascal', 'binomial', 141, 'puzzle', 'Fill in Pascal''s triangle.', null, '{"type":"pascal"}'::jsonb, 'Each entry is the sum of the entry above it and the one above-left.', 'Built Pascal''s triangle incorrectly', null, '{}'::jsonb, ''),
  ('pz-daa-matrixchain', 'matrixchain', 142, 'puzzle', 'Matrix-chain DP table.', null, '{"type":"matrix-chain","matrices":4}'::jsonb, 'Fill diagonals in order of chain length; try every split point and keep the cheapest.', 'Miscomputed a matrix-chain cost', null, '{}'::jsonb, ''),
  ('pz-daa-lcs', 'lcs', 143, 'puzzle', 'Fill in the LCS table.', null, '{"type":"lcs","length":5}'::jsonb, 'Same letters: diagonal + 1. Different letters: the larger of the cell above and the cell to the left.', 'Applied the LCS recurrence incorrectly', null, '{}'::jsonb, ''),
  ('pz-daa-knapsack', 'dp', 144, 'puzzle', '0/1 knapsack table.', null, '{"type":"knapsack"}'::jsonb, 'Compare skipping the item (cell above) with taking it (value + the cell above, w − wᵢ to the left).', 'Applied the knapsack recurrence incorrectly', null, '{}'::jsonb, ''),
  ('pz-daa-subset', 'pnp', 145, 'puzzle', 'Verify vs solve: subset sum.', null, '{"type":"subset-sum"}'::jsonb, 'Try the bigger numbers first, then fill the gap with small ones.', 'Couldn''t find a valid certificate', null, '{}'::jsonb, ''),
  ('pz-daa-indset', 'npc', 146, 'puzzle', 'An NP-complete problem: independent set.', null, '{"type":"np-graph","problem":"independent-set"}'::jsonb, 'Start with vertices that have few edges; each chosen vertex rules out its neighbours.', 'Chose an invalid or too-small independent set', null, '{}'::jsonb, ''),
  ('pz-daa-reduction', 'reductions', 147, 'puzzle', 'Independent set → vertex cover.', null, '{"type":"reduction"}'::jsonb, 'Every edge must touch the cover. What do you get if you take every vertex that is not in the independent set?', 'Didn''t apply the complement reduction', null, '{}'::jsonb, ''),
  ('pz-daa-sat', 'sat', 148, 'puzzle', 'Satisfy the formula.', null, '{"type":"sat","variables":4,"clauses":5}'::jsonb, 'Look for a clause with a single way left to be true and fix that variable first.', 'Left a clause unsatisfied', null, '{}'::jsonb, ''),
  ('pz-daa-tsp', 'tsp', 149, 'puzzle', 'Find the shortest tour.', null, '{"type":"tsp","cities":5}'::jsonb, 'Cheap edges help, but check the total: a greedy tour isn''t always the shortest.', 'Didn''t find the shortest tour', null, '{}'::jsonb, ''),
  ('pz-ds-costs', 'ds-basics', 150, 'puzzle', 'Order the operations by cost.', null, '{"type":"growth","set":"operations","count":6}'::jsonb, 'Think of how many elements each operation has to touch as n grows.', 'Misjudged the cost of an operation', null, '{}'::jsonb, ''),
  ('pz-ds-address', 'ds-array-memory', 151, 'puzzle', 'Compute element addresses.', null, '{"type":"address","order":"row"}'::jsonb, 'Row-major: skip (i − 1) whole rows, then (j − 1) elements, and multiply by the element size.', 'Miscomputed an array address', null, '{}'::jsonb, ''),
  ('pz-ds-shift', 'ds-array-ops', 152, 'puzzle', 'Shift elements to insert or delete.', null, '{"type":"array-shift"}'::jsonb, 'To insert, start shifting from the last element; to delete, start from the element right after the gap.', 'Shifted array elements in the wrong order', null, '{}'::jsonb, ''),
  ('pz-ds-binsearch', 'ds-search', 153, 'puzzle', 'Binary search, step by step.', null, '{"type":"binary-search"}'::jsonb, 'Compare with the middle of the remaining range, then throw away the half that can''t contain the key.', 'Didn''t follow binary search', null, '{}'::jsonb, ''),
  ('pz-ds-sparse', 'ds-sparse', 154, 'puzzle', 'Transpose a sparse matrix.', null, '{"type":"sparse-transpose"}'::jsonb, 'Swap row and column in each triplet, then sort by the new row (and column).', 'Transposed the triplets incorrectly', null, '{}'::jsonb, ''),
  ('pz-ds-recursion', 'ds-recursion', 155, 'puzzle', 'Walk the recursion tree.', null, '{"type":"recursion-tree"}'::jsonb, 'A call runs to completion — all of its own calls — before its caller moves on.', 'Mis-traced the order of recursive calls', null, '{}'::jsonb, ''),
  ('pz-ds-linked', 'ds-linked', 156, 'puzzle', 'Follow the pointers.', null, '{"type":"linked-list"}'::jsonb, 'Start at head and always jump to the address stored in next, wherever it is in memory.', 'Didn''t follow the next pointers', null, '{}'::jsonb, ''),
  ('pz-ds-poly', 'ds-polynomial', 157, 'puzzle', 'Multiply two polynomials.', null, '{"type":"polynomial","op":"multiply"}'::jsonb, 'Multiply each term of p by each term of q (exponents add), then collect equal powers.', 'Combined polynomial terms incorrectly', null, '{}'::jsonb, ''),
  ('pz-ds-stack', 'ds-stack', 158, 'puzzle', 'Pop the right value.', null, '{"type":"stack-queue","kind":"stack"}'::jsonb, 'A pop removes the value pushed most recently that is still on the stack.', 'Popped the wrong value from the stack', null, '{}'::jsonb, ''),
  ('pz-ds-queue', 'ds-queue', 159, 'puzzle', 'Dequeue the right value.', null, '{"type":"stack-queue","kind":"queue"}'::jsonb, 'A dequeue removes the value that has been waiting longest.', 'Dequeued the wrong value', null, '{}'::jsonb, ''),
  ('pz-ds-pq', 'ds-pq', 160, 'puzzle', 'Sift through a min-heap.', null, '{"type":"heap","heap":"min"}'::jsonb, 'In a min-heap the smallest key is at the root: swap with the smaller child, or with a larger parent.', 'Moved the key the wrong way through the heap', null, '{}'::jsonb, ''),
  ('pz-ds-postfix', 'ds-expressions', 161, 'puzzle', 'Infix to postfix.', null, '{"type":"postfix"}'::jsonb, 'Operands come out in their original order; each operator follows its two operands. Mind precedence and brackets.', 'Converted infix to postfix incorrectly', null, '{}'::jsonb, ''),
  ('pz-ds-huffman', 'ds-huffman', 162, 'puzzle', 'Huffman''s algorithm.', null, '{"type":"huffman","symbols":6}'::jsonb, 'Always merge the two trees with the smallest weights.', 'Merged trees that weren''t the two lightest', null, '{}'::jsonb, ''),
  ('pz-ds-general', 'ds-general-threaded', 163, 'puzzle', 'Traverse a general tree.', null, '{"type":"general-tree","order":"preorder"}'::jsonb, 'Visit the node, then each child''s whole subtree from left to right.', 'Traversed the general tree in the wrong order', null, '{}'::jsonb, ''),
  ('pz-ds-trie', 'ds-trie', 164, 'puzzle', 'Search a trie.', null, '{"type":"trie"}'::jsonb, 'Each level is one letter: from the current node, go to the child labelled with the next letter.', 'Didn''t follow the trie path', null, '{}'::jsonb, ''),
  ('pz-ds-merge', 'ds-advanced-sorts', 165, 'puzzle', 'Merge two sorted runs.', null, '{"type":"merge"}'::jsonb, 'Compare only the two front values and take the smaller one.', 'Didn''t merge by comparing the two fronts', null, '{}'::jsonb, ''),
  ('pz-ds-radix', 'ds-keys-external', 166, 'puzzle', 'One radix-sort pass.', null, '{"type":"radix-pass"}'::jsonb, 'Group by the ones digit (0 to 9), keeping the original order inside each group.', 'Did an unstable or wrong-digit radix pass', null, '{}'::jsonb, ''),
  ('pz-ds-hashing', 'ds-hashing', 167, 'puzzle', 'Quadratic probing.', null, '{"type":"hashing","probe":"quadratic","size":11}'::jsonb, 'Try h, then h + 1, h + 4, h + 9 … (mod m) until a slot is free.', 'Placed a key in the wrong slot', null, '{}'::jsonb, ''),
  ('pz-ds-graphrep', 'ds-graph-rep', 168, 'puzzle', 'Adjacency matrix of a digraph.', null, '{"type":"adjacency-matrix","nodes":5,"directed":true}'::jsonb, 'For each arrow u → v set row u, column v only.', 'Built the adjacency matrix incorrectly', null, '{}'::jsonb, ''),
  ('pz-ds-multigraph', 'ds-multigraph', 169, 'puzzle', 'Degrees in a multigraph.', null, '{"type":"degrees"}'::jsonb, 'Count arrowheads for in-degree and arrow tails for out-degree, one for each parallel edge and loop.', 'Miscounted degrees in a multigraph', null, '{}'::jsonb, ''),
  ('pz-la-zn', 'la-structures', 170, 'puzzle', 'Inverses in ℤₙ.', null, '{"type":"zn-inverse"}'::jsonb, 'Try b = 1, 2, … until a·b leaves remainder 1. If gcd(a, n) > 1 there is none.', 'Miscalculated an inverse mod n', null, '{}'::jsonb, ''),
  ('pz-la-closure', 'la-vector-spaces', 171, 'puzzle', 'Test closure under addition.', null, '{"type":"closure"}'::jsonb, 'Add the coordinates of u and v, then check whether the result is on the dashed line.', 'Misjudged closure under addition', null, '{}'::jsonb, ''),
  ('pz-la-r3', 'la-r3', 172, 'puzzle', 'Cross product and volume.', null, '{"type":"cross-product"}'::jsonb, 'u × v = (u₂v₃ − u₃v₂, u₃v₁ − u₁v₃, u₁v₂ − u₂v₁).', 'Miscomputed a cross product', null, '{}'::jsonb, ''),
  ('pz-la-matrixspace', 'la-matrix-space', 173, 'puzzle', 'Coordinates of a matrix.', null, '{"type":"matrix-coords"}'::jsonb, 'Only B₄ has a bottom-right 1, so d is that entry; work backwards through c, b, a.', 'Found the wrong coordinates', null, '{}'::jsonb, ''),
  ('pz-la-polyspace', 'la-poly-space', 174, 'puzzle', 'Coordinates of a polynomial.', null, '{"type":"poly-coords"}'::jsonb, 'c₀ = p(1). Expand (x − 1)² and match the x² and x coefficients for c₂ and c₁.', 'Found the wrong coordinates', null, '{}'::jsonb, ''),
  ('pz-la-complex', 'la-complex-space', 175, 'puzzle', 'Multiply complex numbers.', null, '{"type":"complex","op":"multiply"}'::jsonb, '(a + bi)(c + di) = (ac − bd) + (ad + bc)i, since i² = −1.', 'Miscalculated a complex product', null, '{}'::jsonb, ''),
  ('pz-la-directsum', 'la-direct-sum', 176, 'puzzle', 'Split a vector: U ⊕ W.', null, '{"type":"direct-sum"}'::jsonb, 'From v, move parallel to W until you land on U.', 'Split the vector incorrectly', null, '{}'::jsonb, ''),
  ('pz-la-oblique', 'la-projection', 177, 'puzzle', 'An oblique projection.', null, '{"type":"oblique-projection"}'::jsonb, 'Slide p parallel to d until it meets the line L.', 'Projected along the wrong direction', null, '{}'::jsonb, ''),
  ('pz-la-ranknullity', 'la-rank-nullity', 178, 'puzzle', 'Rank and nullity.', null, '{"type":"rank-nullity"}'::jsonb, 'Row-reduce, count the pivots for the rank; the free columns give the nullity.', 'Misapplied rank–nullity', null, '{}'::jsonb, ''),
  ('pz-la-inverse', 'la-inverse', 179, 'puzzle', 'Invert the matrix.', null, '{"type":"inverse","size":2}'::jsonb, 'For [a b; c d]: swap a and d, negate b and c, divide everything by ad − bc.', 'Computed the inverse incorrectly', null, '{}'::jsonb, ''),
  ('pz-la-changebasis', 'la-change-basis', 180, 'puzzle', 'The matrix in a new basis.', null, '{"type":"change-basis"}'::jsonb, 'Compute AP first (A applied to b₁, b₂), then multiply by P⁻¹ on the left.', 'Changed basis incorrectly', null, '{}'::jsonb, ''),
  ('pz-la-dual', 'la-dual', 181, 'puzzle', 'Find the dual basis.', null, '{"type":"dual-basis"}'::jsonb, 'Set up fᵢ(bⱼ) as equations; the answer is the rows of P⁻¹.', 'Found the wrong dual basis', null, '{}'::jsonb, ''),
  ('pz-la-dettrace', 'la-det-trace', 182, 'puzzle', 'Trace and determinant.', null, '{"type":"det-trace","size":3}'::jsonb, 'Trace: add the diagonal. Determinant: expand along a row, with signs + − +.', 'Miscomputed the trace or determinant', null, '{}'::jsonb, ''),
  ('pz-la-cayley', 'la-cayley', 183, 'puzzle', 'Cayley–Hamilton in action.', null, '{"type":"cayley"}'::jsonb, 'For 2 × 2: p(λ) = λ² − (trace)λ + det. Then A² = (trace)A − (det)I.', 'Misapplied Cayley–Hamilton', null, '{}'::jsonb, ''),
  ('pz-la-diagonalize', 'la-diagonalize', 184, 'puzzle', 'Rebuild A from P and D.', null, '{"type":"diagonalize"}'::jsonb, 'Multiply in the order P·D·P⁻¹; P⁻¹ of a 2 × 2 with det 1 is [d −b; −c a].', 'Assembled PDP⁻¹ incorrectly', null, '{}'::jsonb, ''),
  ('pz-la-jordan', 'la-jordan', 185, 'puzzle', 'Read off the Jordan blocks.', null, '{"type":"jordan"}'::jsonb, 'd₁ = number of blocks; dₖ − dₖ₋₁ = number of blocks of size at least k.', 'Misread the Jordan structure', null, '{}'::jsonb, ''),
